using System;
using System.Collections.Concurrent;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using Microsoft.AspNetCore.Mvc;

namespace SecureVault.Controllers
{
    public class AccountBalance
    {
        public string AccountId { get; set; }
        public decimal Balance { get; set; }
        public long Version { get; set; }
        public DateTime LastModified { get; set; }
    }

    public interface ILedgerStore
    {
        AccountBalance GetBalance(string accountId);
        bool TryTransfer(string fromAccount, string toAccount, decimal amount);
    }

    public class FileLedgerStore : ILedgerStore
    {
        private readonly string _dataDir;
        private readonly ReaderWriterLockSlim _rwLock = new ReaderWriterLockSlim(LockRecursionPolicy.SupportsRecursion);
        private readonly ConcurrentDictionary<string, AccountBalance> _cache = new();

        public FileLedgerStore(string dataDir)
        {
            _dataDir = Path.GetFullPath(dataDir);
            if (!Directory.Exists(_dataDir))
                Directory.CreateDirectory(_dataDir);
        }

        private string GetAccountPath(string accountId)
        {
            var sanitized = Convert.ToHexString(
                SHA256.HashData(Encoding.UTF8.GetBytes(accountId))).Substring(0, 16);
            var path = Path.GetFullPath(Path.Combine(_dataDir, sanitized + ".dat"));
            if (!path.StartsWith(_dataDir + Path.DirectorySeparatorChar))
                throw new InvalidOperationException("Path traversal detected");
            return path;
        }

        public AccountBalance GetBalance(string accountId)
        {
            _rwLock.EnterReadLock();
            try
            {
                return GetBalanceInternal(accountId);
            }
            finally
            {
                _rwLock.ExitReadLock();
            }
        }

        public bool TryTransfer(string fromAccount, string toAccount, decimal amount)
        {
            // Acquire write lock for the entire transfer operation (atomic)
            _rwLock.EnterWriteLock();
            try
            {
                var fromBalance = GetBalanceInternal(fromAccount);
                if (fromBalance == null)
                    return false;

                var toBalance = GetBalanceInternal(toAccount);
                if (toBalance == null)
                    return false;

                if (fromBalance.Balance < amount)
                    return false;

                // Perform atomic debit and credit under single write lock
                var newFromBalance = new AccountBalance
                {
                    AccountId = fromAccount,
                    Balance = fromBalance.Balance - amount,
                    Version = fromBalance.Version + 1,
                    LastModified = DateTime.UtcNow
                };

                var newToBalance = new AccountBalance
                {
                    AccountId = toAccount,
                    Balance = toBalance.Balance + amount,
                    Version = toBalance.Version + 1,
                    LastModified = DateTime.UtcNow
                };

                // Write both atomically
                var fromPath = GetAccountPath(fromAccount);
                var toPath = GetAccountPath(toAccount);

                var fromContent = string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2:O}",
                    newFromBalance.Balance, newFromBalance.Version, newFromBalance.LastModified);
                var toContent = string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2:O}",
                    newToBalance.Balance, newToBalance.Version, newToBalance.LastModified);

                File.WriteAllText(fromPath, fromContent);
                File.WriteAllText(toPath, toContent);

                _cache[fromAccount] = newFromBalance;
                _cache[toAccount] = newToBalance;

                return true;
            }
            finally
            {
                _rwLock.ExitWriteLock();
            }
        }

        private AccountBalance GetBalanceInternal(string accountId)
        {
            if (_cache.TryGetValue(accountId, out var cached))
                return new AccountBalance
                {
                    AccountId = cached.AccountId,
                    Balance = cached.Balance,
                    Version = cached.Version,
                    LastModified = cached.LastModified
                };

            var path = GetAccountPath(accountId);
            if (!File.Exists(path))
                return null;
            var data = File.ReadAllText(path);
            var parts = data.Split('|');
            if (parts.Length != 3)
                throw new InvalidDataException("Corrupted ledger record");

            if (!decimal.TryParse(parts[0], NumberStyles.Number, CultureInfo.InvariantCulture, out var parsedBalance) ||
                !long.TryParse(parts[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedVersion) ||
                !DateTime.TryParse(parts[2], CultureInfo.InvariantCulture,
                    DateTimeStyles.RoundtripKind, out var parsedModified))
            {
                throw new InvalidDataException("Corrupted ledger record");
            }

            var balance = new AccountBalance
            {
                AccountId = accountId,
                Balance = parsedBalance,
                Version = parsedVersion,
                LastModified = parsedModified
            };
            _cache[accountId] = balance;
            return balance;
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class TransferController : ControllerBase
    {
        private readonly ILedgerStore _ledger;

        public TransferController(ILedgerStore ledger)
        {
            _ledger = ledger;
        }

        [HttpPost("transfer")]
        public IActionResult Transfer([FromBody] TransferRequest request)
        {
            if (string.IsNullOrWhiteSpace(request?.FromAccount) ||
                string.IsNullOrWhiteSpace(request?.ToAccount))
                return BadRequest("Invalid accounts");

            if (request.Amount <= 0 || request.Amount > 1_000_000)
                return BadRequest("Invalid amount");

            if (request.FromAccount == request.ToAccount)
                return BadRequest("Cannot transfer to same account");

            var success = _ledger.TryTransfer(
                request.FromAccount,
                request.ToAccount,
                request.Amount);

            if (!success)
                return BadRequest("Transfer failed: insufficient funds or account not found");

            return Ok(new { Message = "Transfer complete" });
        }
    }

    public class TransferRequest
    {
        public string FromAccount { get; set; }
        public string ToAccount { get; set; }
        public decimal Amount { get; set; }
    }
}
